DO $selected_identity$ DECLARE old_source jsonb;actual_source jsonb;selected_source jsonb;doc jsonb;raw_sha text;doc_sha text; BEGIN
 SELECT v.source_snapshot,v.source_sha256,v.document,v.document_sha256 INTO STRICT old_source,raw_sha,doc,doc_sha FROM mission_factory_owner.c352_resource_selection k JOIN mission_factory_owner.c352_resource_versions v ON v.id=k.resource_version_id WHERE k.singleton AND k.enabled;
 IF raw_sha IS DISTINCT FROM mission_factory_owner.sha(old_source) OR doc_sha IS DISTINCT FROM mission_factory_owner.sha(doc) OR doc->>'source_sha256' IS DISTINCT FROM raw_sha OR old_source->>'schema_version' IS DISTINCT FROM 'mission-factory-native-resource-source/1' OR old_source#>>'{generic_policy,mode}' IS DISTINCT FROM 'all' OR NOT mission_factory_owner.keys_exact_v2(old_source->'generic_policy',ARRAY['mode','provider_max_calls','provider_max_cost_usd']) THEN RAISE EXCEPTION 'HUMAN_RESOURCE_REPAIR_LEGACY_INTEGRITY';END IF;
 actual_source:=mission_factory_owner.c352_native_resource_source_v1();
 selected_source:=jsonb_set(actual_source,'{arenas}',coalesce((SELECT jsonb_agg(a ORDER BY ord) FROM jsonb_array_elements(actual_source->'arenas') WITH ORDINALITY AS cur(a,ord) WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(old_source->'arenas') AS old(b) WHERE b->'template_key'=a->'template_key' AND b->'template_version'=a->'template_version')),'[]'::jsonb));
 IF jsonb_set(jsonb_set(old_source,'{generic_policy}',(old_source->'generic_policy')-'mode'),'{schema_version}','"mission-factory-native-resource-source/2"'::jsonb) IS DISTINCT FROM selected_source THEN RAISE EXCEPTION 'HUMAN_RESOURCE_REPAIR_SELECTED_IDENTITY_MISMATCH';END IF;
 END $selected_identity$;
